00055 void CompArea::xRecalcLumaToChroma()
00056 {
00057   const uint32_t csx = getComponentScaleX(compID, chromaFormat);
00058   const uint32_t csy = getComponentScaleY(compID, chromaFormat);
00059 
00060   x      >>= csx;
00061   y      >>= csy;
00062   width  >>= csx;
00063   height >>= csy;
00064 }
00065 
00066 Position CompArea::chromaPos() const
00067 {
00068   if (isLuma(compID))
00069   {
00070     uint32_t scaleX = getComponentScaleX(compID, chromaFormat);
00071     uint32_t scaleY = getComponentScaleY(compID, chromaFormat);
00072 
00073     return Position(x >> scaleX, y >> scaleY);
00074   }
00075   else
00076   {
00077     return *this;
00078   }
00079 }
