00160 bool UnitArea::contains(const UnitArea& other) const
00161 {
00162   bool ret = true;
00163   bool any = false;
00164 
00165   for( const auto &blk : other.blocks )
00166   {
00167     if( blk.valid() && blocks[blk.compID].valid() )
00168     {
00169       ret &= blocks[blk.compID].contains( blk );
00170       any = true;
00171     }
00172   }
00173 
00174   return any && ret;
00175 }
00176 
00177 bool UnitArea::contains( const UnitArea& other, const ChannelType chType ) const
00178 {
00179   bool ret = true;
00180   bool any = false;
00181 
00182   for( const auto &blk : other.blocks )
00183   {
00184     if( toChannelType( blk.compID ) == chType && blk.valid() && blocks[blk.compID].valid() )
00185     {
00186       ret &= blocks[blk.compID].contains( blk );
00187       any = true;
00188     }
00189   }
00190 
00191   return any && ret;
00192 }
