00212 const UnitArea UnitArea::singleComp(const ComponentID compID) const
00213 {
00214   UnitArea ret(chromaFormat);
00215 
00216   for (const auto &blk : blocks)
00217   {
00218     if (blk.compID == compID)
00219     {
00220       ret.blocks.push_back(blk);
00221     }
00222     else
00223     {
00224       ret.blocks.push_back(CompArea());
00225     }
00226   }
00227 
00228   return ret;
00229 }
