00380 const bool CodingUnit::checkCCLMAllowed() const
00381 {
00382   bool allowCCLM = false;
00383 
00384   if( !CS::isDualITree( *cs ) ) //single tree I slice or non-I slice (Note: judging chType is no longer equivalent to checking dual-tree I slice since the local dual-tree is introduced)
00385   {
00386     allowCCLM = true;
00387   }
00388   else if( slice->getSPS()->getCTUSize() <= 32 ) //dual tree, CTUsize < 64
00389   {
00390     allowCCLM = true;
00391   }
00392   else //dual tree, CTU size 64 or 128
00393   {
00394     int depthFor64x64Node = slice->getSPS()->getCTUSize() == 128 ? 1 : 0;
00395     const PartSplit cuSplitTypeDepth1 = CU::getSplitAtDepth( *this, depthFor64x64Node );
00396     const PartSplit cuSplitTypeDepth2 = CU::getSplitAtDepth( *this, depthFor64x64Node + 1 );
00397 
00398     //allow CCLM if 64x64 chroma tree node uses QT split or HBT+VBT split combination
00399     if( cuSplitTypeDepth1 == CU_QUAD_SPLIT || (cuSplitTypeDepth1 == CU_HORZ_SPLIT && cuSplitTypeDepth2 == CU_VERT_SPLIT) )
00400     {
00401       if( chromaFormat == CHROMA_420 )
00402       {
00403         CHECK( !(blocks[COMPONENT_Cb].width <= 16 && blocks[COMPONENT_Cb].height <= 16), "chroma cu size shall be <= 16x16 for YUV420 format" );
00404       }
00405       allowCCLM = true;
00406     }
00407     //allow CCLM if 64x64 chroma tree node uses NS (No Split) and becomes a chroma CU containing 32x32 chroma blocks
00408     else if( cuSplitTypeDepth1 == CU_DONT_SPLIT )
00409     {
00410       if( chromaFormat == CHROMA_420 )
00411       {
00412         CHECK( !(blocks[COMPONENT_Cb].width == 32 && blocks[COMPONENT_Cb].height == 32), "chroma cu size shall be 32x32 for YUV420 format" );
00413       }
00414       allowCCLM = true;
00415     }
00416     //allow CCLM if 64x32 chroma tree node uses NS and becomes a chroma CU containing 32x16 chroma blocks
00417     else if( cuSplitTypeDepth1 == CU_HORZ_SPLIT && cuSplitTypeDepth2 == CU_DONT_SPLIT )
00418     {
00419       if( chromaFormat == CHROMA_420 )
00420       {
00421         CHECK( !(blocks[COMPONENT_Cb].width == 32 && blocks[COMPONENT_Cb].height == 16), "chroma cu size shall be 32x16 for YUV420 format" );
00422       }
00423       allowCCLM = true;
00424     }
00425 
00426     //further check luma conditions
00427     if( allowCCLM )
00428     {
00429       //disallow CCLM if luma 64x64 block uses BT or TT or NS with ISP
00430       const Position lumaRefPos( chromaPos().x << getComponentScaleX( COMPONENT_Cb, chromaFormat ), chromaPos().y << getComponentScaleY( COMPONENT_Cb, chromaFormat ) );
00431       const CodingUnit* colLumaCu = cs->picture->cs->getCU( lumaRefPos, CHANNEL_TYPE_LUMA );
00432 
00433       if( colLumaCu->lwidth() < 64 || colLumaCu->lheight() < 64 ) //further split at 64x64 luma node
00434       {
00435         const PartSplit cuSplitTypeDepth1Luma = CU::getSplitAtDepth( *colLumaCu, depthFor64x64Node );
00436         CHECK( !(cuSplitTypeDepth1Luma >= CU_QUAD_SPLIT && cuSplitTypeDepth1Luma <= CU_TRIV_SPLIT), "split mode shall be BT, TT or QT" );
00437         if( cuSplitTypeDepth1Luma != CU_QUAD_SPLIT )
00438         {
00439           allowCCLM = false;
00440         }
00441       }
00442       else if( colLumaCu->lwidth() == 64 && colLumaCu->lheight() == 64 && colLumaCu->ispMode ) //not split at 64x64 luma node and use ISP mode
00443       {
00444         allowCCLM = false;
00445       }
00446     }
00447   }
00448 
00449   return allowCCLM;
00450 }
00451 
00452 const uint8_t CodingUnit::checkAllowedSbt() const
00453 {
00454   if( !slice->getSPS()->getUseSBT() )
00455   {
00456     return 0;
00457   }
00458 
00459   //check on prediction mode
00460   if (predMode == MODE_INTRA || predMode == MODE_IBC || predMode == MODE_PLT ) //intra, palette or IBC
00461   {
00462     return 0;
00463   }
00464   if( firstPU->ciipFlag )
00465   {
00466     return 0;
00467   }
00468 
00469   uint8_t sbtAllowed = 0;
00470   int cuWidth  = lwidth();
00471   int cuHeight = lheight();
00472   bool allow_type[NUMBER_SBT_IDX];
00473   memset( allow_type, false, NUMBER_SBT_IDX * sizeof( bool ) );
00474 
00475   //parameter
00476   int maxSbtCUSize = cs->sps->getMaxTbSize();
00477   int minSbtCUSize = 1 << ( MIN_CU_LOG2 + 1 );
00478 
00479   //check on size
00480   if( cuWidth > maxSbtCUSize || cuHeight > maxSbtCUSize )
00481   {
00482     return 0;
00483   }
00484 
00485   allow_type[SBT_VER_HALF] = cuWidth  >= minSbtCUSize;
00486   allow_type[SBT_HOR_HALF] = cuHeight >= minSbtCUSize;
00487   allow_type[SBT_VER_QUAD] = cuWidth  >= ( minSbtCUSize << 1 );
00488   allow_type[SBT_HOR_QUAD] = cuHeight >= ( minSbtCUSize << 1 );
00489 
00490   for( int i = 0; i < NUMBER_SBT_IDX; i++ )
00491   {
00492     sbtAllowed += (uint8_t)allow_type[i] << i;
00493   }
00494 
00495   return sbtAllowed;
00496 }
00497 
00498 uint8_t CodingUnit::getSbtTuSplit() const
00499 {
00500   uint8_t sbtTuSplitType = 0;
00501 
00502   switch( getSbtIdx() )
00503   {
00504   case SBT_VER_HALF: sbtTuSplitType = ( getSbtPos() == SBT_POS0 ? 0 : 1 ) + SBT_VER_HALF_POS0_SPLIT; break;
00505   case SBT_HOR_HALF: sbtTuSplitType = ( getSbtPos() == SBT_POS0 ? 0 : 1 ) + SBT_HOR_HALF_POS0_SPLIT; break;
00506   case SBT_VER_QUAD: sbtTuSplitType = ( getSbtPos() == SBT_POS0 ? 0 : 1 ) + SBT_VER_QUAD_POS0_SPLIT; break;
00507   case SBT_HOR_QUAD: sbtTuSplitType = ( getSbtPos() == SBT_POS0 ? 0 : 1 ) + SBT_HOR_QUAD_POS0_SPLIT; break;
00508   default: assert( 0 );  break;
00509   }
00510 
00511   assert( sbtTuSplitType <= SBT_HOR_QUAD_POS1_SPLIT && sbtTuSplitType >= SBT_VER_HALF_POS0_SPLIT );
00512   return sbtTuSplitType;
00513 }
