00580 PredictionUnit& PredictionUnit::operator=(const InterPredictionData& predData)
00581 {
00582   mergeFlag   = predData.mergeFlag;
00583   regularMergeFlag = predData.regularMergeFlag;
00584   mergeIdx    = predData.mergeIdx;
00585   geoSplitDir  = predData.geoSplitDir;
00586   geoMergeIdx0 = predData.geoMergeIdx0;
00587   geoMergeIdx1 = predData.geoMergeIdx1;
00588   mmvdMergeFlag = predData.mmvdMergeFlag;
00589   mmvdMergeIdx = predData.mmvdMergeIdx;
00590   interDir    = predData.interDir;
00591   mergeType   = predData.mergeType;
00592   bv          = predData.bv;
00593   bvd         = predData.bvd;
00594   mvRefine = predData.mvRefine;
00595   for (uint32_t i = 0; i < MAX_NUM_SUBCU_DMVR; i++)
00596   {
00597     mvdL0SubPu[i] = predData.mvdL0SubPu[i];
00598   }
00599   for (uint32_t i = 0; i < NUM_REF_PIC_LIST_01; i++)
