00703 
00704 TransformUnit::TransformUnit(const UnitArea& unit) : UnitArea(unit), cu(nullptr), cs(nullptr), chType( CH_L ), next( nullptr )
00705 {
00706   for( unsigned i = 0; i < MAX_NUM_TBLOCKS; i++ )
00707   {
00708     m_coeffs[i] = nullptr;
00709     m_pcmbuf[i] = nullptr;
00710   }
00711 
00712   for (unsigned i = 0; i < MAX_NUM_TBLOCKS - 1; i++)
00713   {
00714     m_runType[i] = nullptr;
00715   }
00716 
00717   initData();
00718 }
00719 
00720 TransformUnit::TransformUnit(const ChromaFormat _chromaFormat, const Area &_area) : UnitArea(_chromaFormat, _area), cu(nullptr), cs(nullptr), chType( CH_L ), next( nullptr )
00721 {
00722   for( unsigned i = 0; i < MAX_NUM_TBLOCKS; i++ )
00723   {
00724     m_coeffs[i] = nullptr;
00725     m_pcmbuf[i] = nullptr;
00726   }
00727 
00728   for (unsigned i = 0; i < MAX_NUM_TBLOCKS - 1; i++)
00729   {
00730     m_runType[i] = nullptr;
00731   }
00732 
00733   initData();
00734 }
00735 
00736 void TransformUnit::initData()
00737 {
00738   for( unsigned i = 0; i < MAX_NUM_TBLOCKS; i++ )
00739   {
00740     cbf[i]           = 0;
00741     mtsIdx[i]        = MTS_DCT2_DCT2;
00742   }
00743   depth              = 0;
00744   noResidual         = false;
00745   jointCbCr          = 0;
00746   m_chromaResScaleInv = 0;
00747 }
00748 void TransformUnit::init(TCoeff **coeffs, Pel **pcmbuf, bool **runType)
00749 {
00750   uint32_t numBlocks = getNumberValidTBlocks(*cs->pcv);
00751 
00752   for (uint32_t i = 0; i < numBlocks; i++)
00753   {
00754     m_coeffs[i] = coeffs[i];
00755     m_pcmbuf[i] = pcmbuf[i];
00756   }
00757 
00758   // numBlocks is either 1 for 4:0:0, or 3 otherwise. It would perhaps be better to loop over getNumberValidChannels(*cs->pcv.chrFormat) for m_runType.
00759   for (uint32_t i = 0; i < std::max<uint32_t>(2, numBlocks)-1; i++)
00760   {
00761     m_runType[i] = runType[i];
00762   }
00763 }
00764 
00765 TransformUnit& TransformUnit::operator=(const TransformUnit& other)
00766 {
00767   CHECK( chromaFormat != other.chromaFormat, "Incompatible formats" );
00768 
00769   unsigned numBlocks = vtm::getNumberValidTBlocks(*cs->pcv);
00770   for( unsigned i = 0; i < numBlocks; i++ )
00771   {
00772     CHECKD( blocks[i].area() != other.blocks[i].area(), "Transformation units cover different areas" );
00773 
00774     uint32_t area = blocks[i].area();
00775 
00776     if (m_coeffs[i] && other.m_coeffs[i] && m_coeffs[i] != other.m_coeffs[i]) memcpy(m_coeffs[i], other.m_coeffs[i], sizeof(TCoeff) * area);
00777     if (m_pcmbuf[i] && other.m_pcmbuf[i] && m_pcmbuf[i] != other.m_pcmbuf[i]) memcpy(m_pcmbuf[i], other.m_pcmbuf[i], sizeof(Pel   ) * area);
00778     if (cu->slice->getSPS()->getPLTMode() && i < 2)
00779     {
00780       if (m_runType[i]   && other.m_runType[i]   && m_runType[i]   != other.m_runType[i]  ) memcpy(m_runType[i],   other.m_runType[i],   sizeof(bool) * area);
00781     }
00782     cbf[i]           = other.cbf[i];
00783     mtsIdx[i] = other.mtsIdx[i];
00784   }
00785   depth              = other.depth;
00786   noResidual         = other.noResidual;
00787   jointCbCr          = other.jointCbCr;
00788   return *this;
00789 }
00790 
00791 void TransformUnit::copyComponentFrom(const TransformUnit& other, const ComponentID i)
00792 {
00793   CHECK( chromaFormat != other.chromaFormat, "Incompatible formats" );
00794 
00795   CHECKD( blocks[i].area() != other.blocks[i].area(), "Transformation units cover different areas" );
00796 
00797   uint32_t area = blocks[i].area();
00798 
00799   if (m_coeffs[i] && other.m_coeffs[i] && m_coeffs[i] != other.m_coeffs[i]) memcpy(m_coeffs[i], other.m_coeffs[i], sizeof(TCoeff) * area);
00800   if (m_pcmbuf[i] && other.m_pcmbuf[i] && m_pcmbuf[i] != other.m_pcmbuf[i]) memcpy(m_pcmbuf[i], other.m_pcmbuf[i], sizeof(Pel   ) * area);
00801   if ((i == COMPONENT_Y || i == COMPONENT_Cb))
00802   {
00803     if (m_runType[i] && other.m_runType[i] && m_runType[i] != other.m_runType[i])   memcpy(m_runType[i], other.m_runType[i], sizeof(bool) * area);
00804   }
00805 
00806   cbf[i]           = other.cbf[i];
00807   depth            = other.depth;
00808   mtsIdx[i]        = other.mtsIdx[i];
00809   noResidual       = other.noResidual;
00810   jointCbCr        = isChroma( i ) ? other.jointCbCr : jointCbCr;
00811 }
