00831 void TransformUnit::checkTuNoResidual( unsigned idx )
00832 {
00833   if( CU::getSbtIdx( cu->sbtInfo ) == SBT_OFF_DCT )
00834   {
00835     return;
00836   }
00837 
00838   if( ( CU::getSbtPos( cu->sbtInfo ) == SBT_POS0 && idx == 1 ) || ( CU::getSbtPos( cu->sbtInfo ) == SBT_POS1 && idx == 0 ) )
00839   {
00840     noResidual = true;
00841   }
00842 }
00843 
00844 int TransformUnit::getTbAreaAfterCoefZeroOut(ComponentID compID) const
00845 {
00846   int tbArea = blocks[compID].width * blocks[compID].height;
00847   int tbZeroOutWidth = blocks[compID].width;
00848   int tbZeroOutHeight = blocks[compID].height;
00849 
00850   if ( cs->sps->getUseMTS() && cu->sbtInfo != 0 && blocks[compID].width <= 32 && blocks[compID].height <= 32 && compID == COMPONENT_Y )
00851   {
00852     tbZeroOutWidth = (blocks[compID].width == 32) ? 16 : tbZeroOutWidth;
00853     tbZeroOutHeight = (blocks[compID].height == 32) ? 16 : tbZeroOutHeight;
00854   }
00855   tbZeroOutWidth = std::min<int>(JVET_C0024_ZERO_OUT_TH, tbZeroOutWidth);
00856   tbZeroOutHeight = std::min<int>(JVET_C0024_ZERO_OUT_TH, tbZeroOutHeight);
00857   tbArea = tbZeroOutWidth * tbZeroOutHeight;
00858   return tbArea;
00859 }
